const progressStorageKey=window.AIRBORDER_JOURNEY?`airborder-progress:${window.AIRBORDER_JOURNEY.trip}:${window.AIRBORDER_JOURNEY.leg}`:'airborder-progress-v1';
let journeyProgress={phase:'transfer',status:{departure:{},arrival:{},transfer:{}}};
try{const saved=window.AIRBORDER_JOURNEY?null:JSON.parse(sessionStorage.getItem(progressStorageKey));if(saved&&['departure','arrival','transfer'].includes(saved.phase)&&saved.status&&typeof saved.status==='object'){for(const phase of Object.keys(progressSteps))for(const [id,,optional] of progressSteps[phase]){const value=saved.status[phase]?.[id];if(value==='done'||(optional&&value==='not-needed'))journeyProgress.status[phase][id]=value;}journeyProgress.phase=saved.phase;}}catch{}
let progressSync=null,progressSyncStatus=window.AIRBORDER_JOURNEY?'Sign in and load saved journey progress before updating steps':'Progress saved in this browser session';
function saveProgress(event){if(event)progressSync?.enqueue(event);try{sessionStorage.setItem(progressStorageKey,JSON.stringify(journeyProgress));}catch{}}
function visibleProgressSteps(){return progressSteps[journeyProgress.phase].filter(step=>step[3]!=='transfer'||context().transfer);}
// Journey phases record only traveler confirmations and never change the plan or eligibility.
const progressGroups={departure:[['Check-in',['checkin'],'flights'],['Bags',['bagdrop'],'bag'],['Security',['security'],'shield'],['Passport control',['passport'],'shield'],['Gate / board',['gate','board'],'gate']],arrival:[['Land',['landed'],'flights'],['Passport control',['passport'],'shield'],['Bags',['bags'],'bag'],['Customs',['customs'],'shield'],['Exit / travel',['connectivity','transport'],'transfer']],transfer:[['Arrival',['arrival'],'flights'],['Connection',['connection'],'flights'],['Transfer',['bags','airport-transfer'],'transfer'],['Security',['security','passport'],'shield'],['Gate / board',['gate','board'],'gate']]};
function progressTracker(){const steps=visibleProgressSteps(),next=steps.find(([id])=>!journeyProgress.status[journeyProgress.phase][id]);const groups=progressGroups[journeyProgress.phase].map(([label,ids,symbol])=>({label,symbol,ids:ids.filter(id=>steps.some(step=>step[0]===id))})).filter(g=>g.ids.length);const active=Math.max(0,groups.findIndex(g=>g.ids.includes(next?.[0])));const name=journeyProgress.phase[0].toUpperCase()+journeyProgress.phase.slice(1);return `<section class="journey-progress" aria-label="Journey steps"><div class="progress-header"><strong>${name} checklist · ${next?`Step ${active+1} of ${groups.length}`:'Steps reviewed'}</strong><button class="secondary" data-action="view-progress">View steps</button></div><div class="progress-rail">${groups.map((group,i)=>{const done=group.ids.every(id=>journeyProgress.status[journeyProgress.phase][id]);return `<div class="progress-node ${next&&i===active?'current':done?'done':''}" aria-label="${esc(group.label)}: ${next&&i===active?'current':done?'reviewed':'upcoming'}"><span>${icon(group.symbol)}</span><b>${esc(group.label)}</b></div>`;}).join('')}</div><p class="progress-current"><strong>Current step:</strong> ${next?esc(next[1]):'Steps reviewed'}</p></section>`;}
function progressAdvice(phase,airport,stepId){if(!['arrival','transfer'].includes(phase))return '';if(['HND','NRT'].includes(airport)&&['passport','customs'].includes(stepId))return `<p class="progress-advice">If you need to enter Japan, prepare arrival details with <a href="https://www.digital.go.jp/en/policies/visit_japan_web" target="_blank" rel="noopener noreferrer">Visit Japan Web</a>. Confirm entry requirements separately.</p>`;if(['LHR','LGW','STN','LTN','MAN','EDI','BHX'].includes(airport)&&stepId==='passport')return `<p class="progress-advice"><a href="https://www.gov.uk/registered-traveller" target="_blank" rel="noopener noreferrer">Registered Traveller</a> may help eligible members at the UK border. Check eligibility and <a href="https://www.faster-uk-entry.service.gov.uk/about" target="_blank" rel="noopener noreferrer">eGate access</a> before applying.</p>`;return '';}
